CREATE TABLE invoice_counters(year int PRIMARY KEY, next_value bigint NOT NULL DEFAULT 1);
ALTER TABLE invoices ADD COLUMN state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','finalized','void'));
ALTER TABLE invoices ADD COLUMN due_date date;
ALTER TABLE invoices ADD COLUMN lines jsonb NOT NULL DEFAULT '[]';
ALTER TABLE invoices ADD COLUMN subtotal bigint NOT NULL DEFAULT 0;
ALTER TABLE invoices ADD COLUMN tax_rate_bps int NOT NULL DEFAULT 0 CHECK(tax_rate_bps BETWEEN 0 AND 10000);
ALTER TABLE invoices ADD COLUMN tax_amount bigint NOT NULL DEFAULT 0;
ALTER TABLE invoices ADD COLUMN discount bigint NOT NULL DEFAULT 0;
ALTER TABLE invoices ADD COLUMN deposit_applied bigint NOT NULL DEFAULT 0;
ALTER TABLE invoices ADD COLUMN milestone_id uuid REFERENCES milestones(id);
ALTER TABLE invoices ADD COLUMN finalized_at timestamptz;
ALTER TABLE invoices ADD COLUMN business_snapshot jsonb NOT NULL DEFAULT '{}';
ALTER TABLE invoices ADD COLUMN kind text NOT NULL DEFAULT 'standard' CHECK(kind IN ('standard','deposit','milestone','retainer'));
CREATE TABLE invoice_history(id bigserial PRIMARY KEY, invoice_id uuid NOT NULL REFERENCES invoices(id), actor_id uuid REFERENCES users(id), event text NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION protect_finalized_invoice() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.state='finalized' AND (NEW.total,NEW.number,NEW.currency,NEW.org_id,NEW.order_id,NEW.lines,NEW.subtotal,NEW.tax_rate_bps,NEW.tax_amount,NEW.discount,NEW.deposit_applied,NEW.business_snapshot) IS DISTINCT FROM (OLD.total,OLD.number,OLD.currency,OLD.org_id,OLD.order_id,OLD.lines,OLD.subtotal,OLD.tax_rate_bps,OLD.tax_amount,OLD.discount,OLD.deposit_applied,OLD.business_snapshot) THEN RAISE EXCEPTION 'Finalized invoice content is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER finalized_invoice_immutable BEFORE UPDATE ON invoices FOR EACH ROW EXECUTE FUNCTION protect_finalized_invoice();
CREATE TABLE payment_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider text NOT NULL,event_id text NOT NULL,payload_hash text NOT NULL,payment_id uuid REFERENCES payments(id),status text NOT NULL DEFAULT 'received',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,event_id));
CREATE TABLE manual_transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),order_id uuid NOT NULL REFERENCES orders(id),invoice_id uuid REFERENCES invoices(id),amount bigint NOT NULL CHECK(amount>0),currency text NOT NULL,reference text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','verified','rejected')),verified_by uuid REFERENCES users(id),note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE credit_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),invoice_id uuid REFERENCES invoices(id),payment_id uuid REFERENCES payments(id),amount bigint NOT NULL CHECK(amount>0),reason text NOT NULL,number text NOT NULL UNIQUE,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE billing_agreements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),contract_id uuid REFERENCES contracts(id),order_id uuid NOT NULL REFERENCES orders(id),title text NOT NULL,amount bigint NOT NULL CHECK(amount>0),currency text NOT NULL,interval_months int NOT NULL DEFAULT 1 CHECK(interval_months BETWEEN 1 AND 12),next_bill_date date NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','paused','cancel_requested','cancelled')),kind text NOT NULL DEFAULT 'maintenance',cancel_reason text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE recurring_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),agreement_id uuid NOT NULL REFERENCES billing_agreements(id),period date NOT NULL,invoice_id uuid NOT NULL REFERENCES invoices(id),UNIQUE(agreement_id,period));
CREATE TABLE cms_pages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,title text NOT NULL,kind text NOT NULL,revision int NOT NULL DEFAULT 1,state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','published','archived')),content jsonb NOT NULL DEFAULT '{}',published_content jsonb,seo jsonb NOT NULL DEFAULT '{}',published_seo jsonb,updated_by uuid REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz);
CREATE TABLE cms_revisions(id bigserial PRIMARY KEY,page_id uuid NOT NULL REFERENCES cms_pages(id),revision int NOT NULL,event text NOT NULL,content jsonb NOT NULL,seo jsonb NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE redirects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source text NOT NULL UNIQUE,destination text NOT NULL,status int NOT NULL DEFAULT 301 CHECK(status IN(301,302,307,308)),enabled boolean NOT NULL DEFAULT true);
CREATE TABLE project_team(project_id uuid NOT NULL REFERENCES projects(id),user_id uuid NOT NULL REFERENCES users(id),role text NOT NULL DEFAULT 'developer',PRIMARY KEY(project_id,user_id));
CREATE TABLE task_dependencies(task_id uuid NOT NULL REFERENCES tasks(id),depends_on uuid NOT NULL REFERENCES tasks(id),PRIMARY KEY(task_id,depends_on),CHECK(task_id<>depends_on));
CREATE TABLE time_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),project_id uuid NOT NULL REFERENCES projects(id),task_id uuid REFERENCES tasks(id),user_id uuid NOT NULL REFERENCES users(id),minutes int NOT NULL CHECK(minutes BETWEEN 1 AND 1440),note text NOT NULL,work_date date NOT NULL DEFAULT CURRENT_DATE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE project_history(id bigserial PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations(id),project_id uuid NOT NULL REFERENCES projects(id),actor_id uuid REFERENCES users(id),event text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE messages ADD COLUMN file_ids uuid[] NOT NULL DEFAULT '{}';
ALTER TABLE messages ADD COLUMN reply_to uuid REFERENCES messages(id);
ALTER TABLE outbox ADD COLUMN attempts int NOT NULL DEFAULT 0;
ALTER TABLE outbox ADD COLUMN available_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE outbox ADD COLUMN locked_at timestamptz;
ALTER TABLE outbox ADD COLUMN sent_at timestamptz;
ALTER TABLE outbox ADD COLUMN last_error text;
ALTER TABLE outbox ADD COLUMN delivery_id text;
ALTER TABLE outbox ADD COLUMN dedupe_key text UNIQUE;
CREATE TABLE worker_heartbeats(name text PRIMARY KEY,last_seen timestamptz NOT NULL DEFAULT now(),status text NOT NULL);
CREATE TABLE login_failures(identity_hash text PRIMARY KEY,failures int NOT NULL DEFAULT 0,locked_until timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE security_events(id bigserial PRIMARY KEY,user_id uuid REFERENCES users(id),event text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_allocations(payment_id uuid NOT NULL REFERENCES payments(id),invoice_id uuid NOT NULL REFERENCES invoices(id),amount bigint NOT NULL CHECK(amount>0),PRIMARY KEY(payment_id,invoice_id));
ALTER TABLE files ADD COLUMN public_approved boolean NOT NULL DEFAULT false;
